        exclude: m.get_one::<String>("EXCLUDE").cloned(),
        exclude_header: m
            .get_many::<Regex>("EXCLUDE_HEADER")
            .map(|v| v.cloned().collect()),
        header_field: m
            .get_many::<Regex>("HEADER_FIELD")
            .map(|v| v.cloned().collect()),
        header_is_regex: m.get_flag("header-is-regex"),
        try_decompress: m.get_flag("try-decompress"),
        try_compress: m.get_flag("try-compress"),
        compression_threads: *m.get_one::<usize>("COMPRESSION_THREADS").unwrap(),
        compression_level: *m.get_one::<u32>("COMPRESSION_LEVEL").unwrap(),
        no_mmap: m.get_flag("no-mmap"),
        crlf: m.get_flag("crlf"),
    }
}

