// ---------- escape decoding ----------
fn parse_escape_bytes(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(b.len());
    let mut i = 0usize;
    while i < b.len() {
        let c = b[i];
        if c != b'\\' {
            out.push(c);
            i += 1;
            continue;
        }
        if i + 1 >= b.len() {
            out.push(b'\\');
            i += 1;
            continue;
        }
        match b[i + 1] {
            b'n' => {
                out.push(b'\n');
                i += 2;
            }
            b'r' => {
                out.push(b'\r');
                i += 2;
            }
            b't' => {
                out.push(b'\t');
                i += 2;
            }
            b'0' => {
                out.push(0);
                i += 2;
            }
            b'\\' => {
                out.push(b'\\');
                i += 2;
            }
            b'x' => {
                if i + 3 < b.len() + 1 && i + 3 <= b.len() - 1 + 1 {
                    // need two chars after x
                }
                if i + 3 < b.len() || i + 3 == b.len() {
                    // handled below by explicit check
                }
                if i + 3 <= b.len() - 1 {
                    let h = [b[i + 2], b[i + 3]];
                    let hs = std::str::from_utf8(&h).unwrap_or("");
                    if hs.chars().all(|ch| ch.is_ascii_hexdigit()) {
                        let v = u8::from_str_radix(hs, 16).unwrap();
                        out.push(v);
                        i += 4;
                        continue;
                    }
                }
                out.push(b'\\');
                i += 1;
            }
            _ => {
                out.push(b'\\');
                i += 1;
            }
        }
    }
    out
}

// ---------- field ranges ----------
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FieldRange {
    low: usize,      // 1-based
    high: usize,     // inclusive, usize::MAX = open
}

enum FieldParseError {
    Invalid(String),
    Zero(usize),
    Order(usize, usize),
}
impl std::fmt::Display for FieldParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FieldParseError::Invalid(s) => write!(f, "Failed to parse field: {}", s),
            FieldParseError::Zero(n) => write!(f, "Fields and positions are numbered from 1: {}", n),
            FieldParseError::Order(lo, hi) => {
                write!(f, "High end of range less than low end of range: {}-{}", lo, hi)
            }
        }
    }
}

fn parse_field_ranges(s: &str) -> Result<Vec<FieldRange>, FieldParseError> {
    let mut ranges = Vec::new();
    for token in s.split(',') {
        let range = if let Some(rest) = token.strip_prefix('-') {
            match rest.parse::<usize>() {
                Err(_) => return Err(FieldParseError::Invalid(rest.to_string())),
                Ok(0) => return Err(FieldParseError::Zero(0)),
                Ok(v) => FieldRange { low: 1, high: v },
            }
        } else if let Some(rest) = token.strip_suffix('-') {
            // token does not start with '-' here, and ends with '-'
            if token.contains('-') && !token.starts_with('-') {
                // fallthrough handled below? "ab-" etc: rest is token without trailing '-'
                match rest.parse::<usize>() {
                    Err(_) => return Err(FieldParseError::Invalid(rest.to_string())),
                    Ok(0) => return Err(FieldParseError::Zero(0)),
                    Ok(v) => FieldRange {
                        low: v,
                        high: usize::MAX,
                    },
                }
            } else {
                match rest.parse::<usize>() {
                    Err(_) => return Err(FieldParseError::Invalid(rest.to_string())),
                    Ok(0) => return Err(FieldParseError::Zero(0)),
                    Ok(v) => FieldRange {
                        low: v,
                        high: usize::MAX,
                    },
                }
            }
        } else if token.contains('-') {
            let (a, b) = token.split_once('-').unwrap();
            let lo = a.parse::<usize>();
            let hi = b.parse::<usize>();
            match (lo, hi) {
                (Ok(lo), Ok(hi)) => {
                    if lo == 0 {
                        return Err(FieldParseError::Zero(lo));
                    }
                    if hi < lo {
                        return Err(FieldParseError::Order(lo, hi));
                    }
                    FieldRange { low: lo, high: hi }
                }
                _ => return Err(FieldParseError::Invalid(token.to_string())),
            }
        } else {
            match token.parse::<usize>() {
                Err(_) => return Err(FieldParseError::Invalid(token.to_string())),
                Ok(0) => return Err(FieldParseError::Zero(0)),
                Ok(v) => FieldRange { low: v, high: v },
            }
        };
        ranges.push(range);
    }
    Ok(ranges)
}

fn parse_field_ranges_or_exit(s: &str) -> Vec<FieldRange> {
    match parse_field_ranges(s) {
        Ok(r) => r,
        Err(e) => log_error_exit(&e.to_string()),
    }
}

fn remove_ranges(selection: &mut Vec<FieldRange>, removals: &[FieldRange]) {
    for rem in removals {
        let mut out: Vec<FieldRange> = Vec::with_capacity(selection.len());
        for r in selection.iter() {
            if rem.high < r.low || rem.low > r.high {
                out.push(*r);
                continue;
            }
            // overlap
            if rem.low > r.low {
                out.push(FieldRange {
                    low: r.low,
                    high: rem.low - 1,
                });
            }
            if rem.high < r.high {
                out.push(FieldRange {
                    low: rem.high + 1,
                    high: r.high,
                });
            }
        }
        *selection = out;
        if selection.is_empty() {
            // keep processing removals is harmless (stays empty)
        }
    }
}

fn expand_ranges(ranges: &[FieldRange], num_fields: usize) -> Vec<usize> {
    let mut used = vec![false; num_fields];
    let mut out: Vec<usize> = Vec::new();
    for r in ranges {
        if r.low > num_fields {
            continue;
        }
        let hi = std::cmp::min(r.high, num_fields);
        if hi < r.low {
            continue;
        }
        for idx in r.low..=hi {
            let z = idx - 1;
            if !used[z] {
                used[z] = true;
                out.push(z);
            }
        }
    }
    out
}

// ---------- delimiter ----------
enum Delimiter {
    Literal(Vec<u8>),
    Regex(regex::bytes::Regex),
}

fn split_line<'a>(line: &'a [u8], delim: &Delimiter) -> Vec<&'a [u8]> {
    match delim {
        Delimiter::Literal(d) => {
            if d.is_empty() {
                let mut v: Vec<&[u8]> = Vec::with_capacity(line.len() + 2);
                v.push(&line[0..0]);
                for i in 0..line.len() {
                    v.push(&line[i..i + 1]);
                }
                v.push(&line[line.len()..]);
                return v;
            }
            if d.len() == 1 {
                return line.split(|b| *b == d[0]).collect();
            }
            let mut v = Vec::new();
            let mut start = 0usize;
            for pos in memchr::memmem::find_iter(line, d.as_slice()) {
                v.push(&line[start..pos]);
                start = pos + d.len();
            }
            v.push(&line[start..]);
            v
        }
        Delimiter::Regex(re) => re.split(line).collect(),
    }
}

// ---------- gzip (BGZF-like) output ----------
const BGZF_EOF: &[u8] = b"\x1f\x8b\x08\x04\x00\x00\x00\x00\x00\xff\x06\x00\x42\x43\x02\x00\x1b\x00\x03\x00\x00\x00\x00\x00\x00\x00\x00\x00";
const BLOCK_SIZE: usize = 65280;

fn crc32(data: &[u8]) -> u32 {
    // IEEE CRC32, table generated on the fly per call is too slow for large;
    // use a simple loop with a static polynomial via crc32fast-like manual:
    // We implement a small cached table using once.
    use std::sync::OnceLock;
    static TABLE: OnceLock<[u32; 256]> = OnceLock::new();
    let table = TABLE.get_or_init(|| {
        let mut t = [0u32; 256];
        for i in 0..256u32 {
            let mut c = i;
            for _ in 0..8 {
                c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
            }
            t[i as usize] = c;
        }
        t
    });
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFF_FFFF
}

fn deflate_stored(data: &[u8]) -> Vec<u8> {
    // one stored block (data < 65536 in our usage, but handle general stored chunking)
    let mut out = Vec::new();
    if data.is_empty() {
        out.extend_from_slice(&[0x01, 0x00, 0x00, 0xFF, 0xFF]);
        return out;
    }
    let mut chunks: Vec<&[u8]> = data.chunks(65535).collect();
    let last = chunks.len() - 1;
    for (i, ch) in chunks.drain(..).enumerate() {
        let final_bit: u8 = if i == last { 0x01 } else { 0x00 };
        out.push(final_bit);
        let len = ch.len() as u16;
        out.extend_from_slice(&len.to_le_bytes());
        out.extend_from_slice(&(!len).to_le_bytes());
        out.extend_from_slice(ch);
    }
    out
}

fn deflate_chunk(data: &[u8], level: u32) -> Vec<u8> {
    if data.len() < 32 {
        return deflate_stored(data);
    }
    let lvl = std::cmp::min(level, 10);
    let mut enc = flate2::write::DeflateEncoder::new(Vec::new(), flate2::Compression::new(lvl));
    let _ = enc.write_all(data);
    enc.finish().unwrap_or_default()
}

struct PigzWriter {
    inner: Box<dyn Write>,
    buf: Vec<u8>,
    level: u32,
    wrote_any_block: bool,
    finished: bool,
}
impl PigzWriter {
    fn new(inner: Box<dyn Write>, level: u32) -> Self {
        PigzWriter {
            inner,
            buf: Vec::new(),
            level,
            wrote_any_block: false,
            finished: false,
        }
    }
    fn write_block(&mut self, data: &[u8]) -> io::Result<()> {
        let deflate = deflate_chunk(data, self.level);
        let total_len = 18 + deflate.len() + 8;
        let xfl: u8 = if self.level >= 9 {
            2
        } else if self.level < 2 {
            4
        } else {
            0
        };
        let mut header: Vec<u8> = Vec::with_capacity(18);
        header.extend_from_slice(&[0x1f, 0x8b, 0x08, 0x04, 0, 0, 0, 0, xfl, 0xff, 0x06, 0x00, b'B', b'C', 0x02, 0x00]);
        header.extend_from_slice(&((total_len as u16).wrapping_sub(1)).to_le_bytes());
        // 18 bytes
        self.inner.write_all(&header)?;
        self.inner.write_all(&deflate)?;
        self.inner.write_all(&crc32(data).to_le_bytes())?;
        self.inner.write_all(&(data.len() as u32).to_le_bytes())?;
        self.wrote_any_block = true;
        Ok(())
    }
    fn finish_inner(&mut self) -> io::Result<()> {
        if self.finished {
            return Ok(());
        }
        self.finished = true;
        if !self.buf.is_empty() || !self.wrote_any_block {
            let data = std::mem::take(&mut self.buf);
            self.write_block(&data)?;
        }
        self.inner.write_all(BGZF_EOF)?;
        self.inner.flush()?;
        Ok(())
    }
}
impl Write for PigzWriter {
    fn write(&mut self, data: &[u8]) -> io::Result<usize> {
        let mut rest = data;
        while !rest.is_empty() {
            let space = BLOCK_SIZE - self.buf.len();
            let take = std::cmp::min(space, rest.len());
            self.buf.extend_from_slice(&rest[..take]);
            rest = &rest[take..];
            if self.buf.len() == BLOCK_SIZE {
                let block = std::mem::take(&mut self.buf);
                self.write_block(&block)?;
            }
        }
        Ok(data.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        // do not flush partial gzip block on flush; only flush underlying
        self.inner.flush()
    }
}
impl Drop for PigzWriter {
    fn drop(&mut self) {
        let _ = self.finish_inner();
    }
}

enum OutputWriter {
    Plain(Box<dyn Write>),
    Pigz(PigzWriter),
}
impl Write for OutputWriter {
    fn write(&mut self, data: &[u8]) -> io::Result<usize> {
        match self {
            OutputWriter::Plain(w) => w.write(data),
            OutputWriter::Pigz(w) => w.write(data),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            OutputWriter::Plain(w) => w.flush(),
            OutputWriter::Pigz(w) => w.flush(),
        }
    }
}

// ---------- which / external decompress ----------
fn which_program(name: &str) -> Option<PathBuf> {
    let path_var = std::env::var_os("PATH")?;
    for entry in std::env::split_paths(&path_var) {
        let dir = if entry.as_os_str().is_empty() {
            PathBuf::from(".")
        } else {
            entry
        };
        let candidate = dir.join(name);
        if candidate.is_file() && is_executable(&candidate) {
            return Some(candidate);
        }
    }
    None
}
#[cfg(unix)]
fn is_executable(p: &Path) -> bool {
    use std::os::unix::fs::PermissionsExt;
    match std::fs::metadata(p) {
        Ok(m) => m.permissions().mode() & 0o111 != 0,
        Err(_) => false,
    }
}
#[cfg(not(unix))]
fn is_executable(_p: &Path) -> bool {
    true
}

enum ExternalKind {
    Bzip2,
    Xz,
    XzLzma,
    Zstd,
    Lz4,
    Gzip,
}
fn external_spec(kind: &ExternalKind, prog: &str, file: &Path) -> (String, Vec<std::ffi::OsString>) {
    let p = file.as_os_str().to_os_string();
    match kind {
        ExternalKind::Bzip2 => ("bzip2".into(), vec!["-d".into(), "-c".into(), p]),
        ExternalKind::Xz => ("xz".into(), vec!["-d".into(), "-c".into(), p]),
        ExternalKind::XzLzma => (
            "xz".into(),
            vec!["--format=lzma".into(), "-d".into(), "-c".into(), p],
        ),
        ExternalKind::Zstd => ("zstd".into(), vec!["-q".into(), "-d".into(), "-c".into(), p]),
        ExternalKind::Lz4 => ("lz4".into(), vec!["-d".into(), "-c".into(), p]),
        ExternalKind::Gzip => ("gzip".into(), vec!["-d".into(), "-c".into(), p]),
    }
}

fn run_external(kind: &ExternalKind, file: &Path) -> Option<Vec<u8>> {
    // returns Some(data) if a program was found (caller must handle errors via exit),
    // None if no program found -> caller treats the file as plain.
    let prog_name = match kind {
        ExternalKind::Bzip2 => "bzip2",
        ExternalKind::Xz | ExternalKind::XzLzma => "xz",
        ExternalKind::Zstd => "zstd",
        ExternalKind::Lz4 => "lz4",
        ExternalKind::Gzip => "gzip",
    };
    let _ = prog;
    let found = which_program(prog_name)?;
    let (_name, argv) = external_spec(kind, prog_name, file);
    let output = match ProcCommand::new(&found).args(&argv).output() {
        Ok(o) => o,
        Err(e) => log_io_error_exit(&e),
    };
    if !output.status.success() {
        if output.stderr.is_empty() {
            log_error_exit("<stderr is empty>");
        } else {
            let dashes = "-".repeat(79);
            let stderr_text = String::from_utf8_lossy(&output.stderr);
            let trimmed = stderr_text.trim();
            let indented = trimmed.replace('\n', "\n    ");
            let msg = format!("\n    {}\n    {}\n    {}", dashes, indented, dashes);
            log_error_exit(&msg);
        }
    }
    Some(output.stdout)
}

// ---------- inputs ----------
fn file_extension_bytes(path: &Path) -> Option<Vec<u8>> {
    let name: &std::ffi::OsStr = path.file_name()?;
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStrExt;
        let bytes = name.as_bytes();
        let pos = bytes.iter().rposition(|b| *b == b'.')?;
        Some(bytes[pos + 1..].to_vec())
    }
    #[cfg(not(unix))]
    {
        let s = name.to_string_lossy();
        let pos = s.rfind('.')?;
        Some(s.as_bytes()[pos + 1..].to_vec())
    }
}

fn open_file_plain(path: &Path) -> Box<dyn Read> {
    match File::open(path) {
        Ok(f) => Box::new(f),
        Err(e) => log_io_error_exit(&e),
    }
}

fn make_reader(input: &InputKind, args: &Args) -> Box<dyn BufRead> {
    match input {
        InputKind::Stdin => {
            if args.try_decompress {
                Box::new(BufReader::new(MultiGzDecoder::new(io::stdin())))
            } else {
                Box::new(BufReader::new(io::stdin()))
            }
        }
        InputKind::File(path) => {
            if args.try_decompress {
                if let Some(ext) = file_extension_bytes(path) {
                    match ext.as_slice() {
                        b"gz" => {
                            let f = open_file_plain(path);
                            return Box::new(BufReader::new(MultiGzDecoder::new(f)));
                        }
                        b"bz2" | b"tbz2" => {
                            if let Some(data) = run_external(&ExternalKind::Bzip2, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                            // fall through to plain
                        }
                        b"xz" | b"txz" => {
                            if let Some(data) = run_external(&ExternalKind::Xz, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                        }
                        b"lzma" => {
                            if let Some(data) = run_external(&ExternalKind::XzLzma, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                        }
                        b"zst" | b"zstd" => {
                            if let Some(data) = run_external(&ExternalKind::Zstd, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                        }
                        b"lz4" => {
                            if let Some(data) = run_external(&ExternalKind::Lz4, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                        }
                        b"tgz" | b"Z" => {
                            if let Some(data) = run_external(&ExternalKind::Gzip, path) {
                                return Box::new(BufReader::new(Cursor::new(data)));
                            }
                        }
                        _ => {}
                    }
                }
            }
            let f = open_file_plain(path);
            Box::new(BufReader::new(f))
        }
    }
}

enum InputKind {
    Stdin,
    File(PathBuf),
}

// ---------- main processing ----------
struct Config {
    delim: Delimiter,
    output_delim: Vec<u8>,
    line_terminator: &'static [u8],
    crlf: bool,
}

fn strip_line<'a>(line: &'a [u8], crlf: bool) -> &'a [u8] {
    if crlf {
        if line.ends_with(b"\r\n") {
            &line[..line.len() - 2]
        } else {
            line
        }
    } else if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    }
}

fn header_matches(pattern: &Regex, headers: &[String], as_regex: bool) -> Vec<usize> {
    let mut out = Vec::new();
    for (i, h) in headers.iter().enumerate() {
        let m = if as_regex {
            pattern.is_match(h)
        } else {
            h == pattern.as_str()
        };
        if m {
            out.push(i);
        }
    }
    out
}

fn write_out<W: Write>(writer: &mut W, bytes: &[u8]) {
    if let Err(e) = writer.write_all(bytes) {
        if e.kind() == io::ErrorKind::BrokenPipe {
            process::exit(0);
        } else {
            log_io_error_exit(&e);
        }
    }
}

fn process_one_line<W: Write>(
    line: &[u8],
    selection: &[FieldRange],
    cfg: &Config,
    writer: &mut W,
) {
    let fields = split_line(line, &cfg.delim);
    let indices = expand_ranges(selection, fields.len());
    let mut out: Vec<u8> = Vec::new();
    for (n, idx) in indices.iter().enumerate() {
        if n > 0 {
            out.extend_from_slice(&cfg.output_delim);
        }
        out.extend_from_slice(fields[*idx]);
    }
    out.extend_from_slice(cfg.line_terminator);
    write_out(writer, &out);
}

fn process_rest<R: BufRead, W: Write>(
    reader: &mut R,
    selection: &[FieldRange],
    cfg: &Config,
    writer: &mut W,
) {
    loop {
        let mut buf: Vec<u8> = Vec::new();
        match reader.read_until(b'\n', &mut buf) {
            Ok(0) => break,
            Ok(_) => {
                let content = strip_line(&buf, cfg.crlf);
                // need owned because buf reused? content borrows buf, process before next iter
                let owned: Vec<u8> = content.to_vec();
                process_one_line(&owned, selection, cfg, writer);
            }
            Err(e) => log_io_error_exit(&e),
        }
    }
}

fn run() -> Result<()> {
    let args = parse_args();

    // Open output first (errors returned via anyhow -> "Error: ...")
    let underlying: Box<dyn Write> = if let Some(ref out_path) = args.output {
        let f = File::create(out_path).with_context(|| {
            format!("Failed to open {} for writing.", out_path.display())
        })?;
        Box::new(f)
    } else {
        Box::new(io::stdout())
    };
    let output_writer: OutputWriter = if args.try_compress {
        OutputWriter::Pigz(PigzWriter::new(underlying, args.compression_level))
    } else {
        OutputWriter::Plain(underlying)
    };
    let mut writer = BufWriter::new(output_writer);

    // delimiter (errors returned)
    let (delim, literal_string): (Delimiter, Option<String>) = if args.delim_is_literal {
        let bytes = parse_escape_bytes(&args.delimiter);
        let s = String::from_utf8(bytes)?;
        (Delimiter::Literal(s.as_bytes().to_vec()), Some(s))
    } else {
        let re = regex::bytes::Regex::new(&args.delimiter)?;
        (Delimiter::Regex(re), None)
    };
    let output_delim: Vec<u8> = if args.use_input_delim {
        if let Some(ref ls) = literal_string {
            ls.as_bytes().to_vec()
        } else {
            parse_escape_bytes(&args.output_delimiter)
        }
    } else {
        parse_escape_bytes(&args.output_delimiter)
    };

    // fields, then excludes
    let fields_ranges: Option<Vec<FieldRange>> = args
        .fields
        .as_ref()
        .map(|s| parse_field_ranges_or_exit(s));
    let exclude_ranges: Option<Vec<FieldRange>> = args
        .exclude
        .as_ref()
        .map(|s| parse_field_ranges_or_exit(s));

    let cfg = Config {
        delim,
        output_delim,
        line_terminator: if args.crlf { b"\r\n" } else { b"\n" },
        crlf: args.crlf,
    };

    let has_header_fields = args.header_field.is_some();
    let has_exclude_headers = args.exclude_header.is_some();
    let header_needed = has_header_fields || has_exclude_headers;

    let inputs: Vec<InputKind> = if args.inputs.is_empty() {
        vec![InputKind::Stdin]
    } else {
        args.inputs
            .iter()
            .map(|p| {
                if p.as_os_str() == OsStr::new("-") {
                    InputKind::Stdin
                } else {
                    InputKind::File(p.clone())
                }
            })
            .collect()
    };

    for input in &inputs {
        let mut reader = make_reader(input, &args);
        if header_needed {
            // read header line as String
            let mut header_string = String::new();
            match reader.read_line(&mut header_string) {
                Ok(_) => {}
                Err(e) => log_io_error_exit(&e),
            }
            let header_content_owned: Vec<u8> =
                strip_line(header_string.as_bytes(), cfg.crlf).to_vec();
            let header_fields_bytes = split_line(&header_content_owned, &cfg.delim);
            let headers: Vec<String> = header_fields_bytes
                .iter()
                .map(|b| String::from_utf8_lossy(b).into_owned())
                .collect();

            // base selection
            let mut selection: Vec<FieldRange> = if let Some(ref fr) = fields_ranges {
                fr.clone()
            } else if has_header_fields {
                Vec::new()
            } else {
                vec![FieldRange {
                    low: 1,
                    high: usize::MAX,
                }]
            };

            if let Some(ref patterns) = args.header_field {
                let mut per_pattern: Vec<Vec<usize>> = Vec::new();
                let mut any = false;
                for pat in patterns {
                    let m = header_matches(pat, &headers, args.header_is_regex);
                    if !m.is_empty() {
                        any = true;
                    }
                    per_pattern.push(m);
                }
                if !any {
                    log_error_exit("No headers matched");
                }
                for (i, m) in per_pattern.iter().enumerate() {
                    if m.is_empty() {
                        log_error_exit(&format!(
                            "Header not found: {}",
                            patterns[i].as_str()
                        ));
                    }
                }
                for m in &per_pattern {
                    for &idx in m {
                        selection.push(FieldRange {
                            low: idx + 1,
                            high: idx + 1,
                        });
                    }
                }
            }

            if let Some(ref excl) = exclude_ranges {
                remove_ranges(&mut selection, excl);
            }

            if let Some(ref epatterns) = args.exclude_header {
                let mut removal: Vec<FieldRange> = Vec::new();
                let mut seen: HashSet<usize> = HashSet::new();
                for pat in epatterns {
                    for idx in header_matches(pat, &headers, args.header_is_regex) {
                        if seen.insert(idx) {
                            removal.push(FieldRange {
                                low: idx + 1,
                                high: idx + 1,
                            });
                        }
                    }
                }
                if selection.is_empty() && !removal.is_empty() {
                    fake_field_range_panic();
                }
                if !removal.is_empty() {
                    remove_ranges(&mut selection, &removal);
                }
            }

            if selection.is_empty() {
                continue;
            }

            if !header_content_owned.is_empty() {
                process_one_line(&header_content_owned, &selection, &cfg, &mut writer);
            }
            process_rest(&mut reader, &selection, &cfg, &mut writer);
        } else {
            let mut selection: Vec<FieldRange> = if let Some(ref fr) = fields_ranges {
                fr.clone()
            } else {
                vec![FieldRange {
                    low: 1,
                    high: usize::MAX,
                }]
            };
            if let Some(ref excl) = exclude_ranges {
                remove_ranges(&mut selection, excl);
            }
            if selection.is_empty() {
                continue;
            }
            process_rest(&mut reader, &selection, &cfg, &mut writer);
        }
    }

    // success: drop writer to flush / finish gzip
    drop(writer);
    Ok(())
}

fn main() -> Result<()> {
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("error")).init();
    run()
}
RS"}

