import subprocess, itertools

def run(spec):
    p=subprocess.run(["./executable","-f",spec], input=b"a b c d e f g h\n", capture_output=True)
    return [ord(x)-97 for x in p.stdout.decode().strip().split("\t")] if p.stdout.strip() else []

vals=[(0,1),(1,2),(0,2),(2,4),(1,4),(3,5),(0,5),(2,2),(4,4),(5,6)]
specs=[]
for a in vals:
 for b in vals:
  specs.append((a,b))
  for c in vals[::2]:
    specs.append((a,b,c))
ACT={}
for ranges in specs:
    spec=",".join(f"{l+1}-{r+1}" for l,r in ranges)
    ACT[spec]=run(spec)

def subtract_one(seg, rem):
    l,r=rem; a,b=seg
    if r<a or l>b: return [seg]
    out=[]
    if a<l: out.append((a,l-1))
    if r<b: out.append((r+1,b))
    return out
def subtract_many(segs, rem):
    out=[]
    for s in segs: out.extend(subtract_one(s,rem))
    return out

def trim_edge(E,N):
    el,er=E; l,r=N
    if er<l or el>r: return [E]
    if l<=el and r>=er: return []
    if l>el and r<er: return [E]
    if l<=el: return [(r+1,er)]
    return [(el,l-1)]

def insert_variant(ranges, trim_mode, modify_mode, stop_first):
    L=[]
    for N in ranges:
        # modify N computation uses original L
        append_segs=[N]
        if modify_mode=='sub_all':
            for E in L: append_segs=subtract_many(append_segs, E)
        elif modify_mode=='sub_subset':
            for E in L:
                if E[0]>=N[0] and E[1]<=N[1]: append_segs=subtract_many(append_segs,E)
        elif modify_mode=='sub_first_shares_low':
            for E in L:
                if E[0]==N[0]: append_segs=subtract_many(append_segs,E)
        newL=[]; stopped=False
        for E in L:
            overlap=not (E[1]<N[0] or E[0]>N[1])
            if stop_first and stopped and overlap:
                newL.append(E); continue
            if not overlap:
                newL.append(E); continue
            # overlapping
            if trim_mode=='split': newL.extend(subtract_one(E,N))
            elif trim_mode=='edge': newL.extend(trim_edge(E,N))
            elif trim_mode=='none': newL.append(E)
            elif trim_mode=='drop': pass
            if stop_first: stopped=True
        newL.extend(append_segs)
        L=newL
    out=[];seen=set()
    for l,r in L:
        for i in range(l,r+1):
            if i not in seen: seen.add(i); out.append(i)
    return out

results=[]
for trim_mode in ['split','edge','none','drop']:
 for modify_mode in ['none','sub_all','sub_subset','sub_first_shares_low']:
  for stop_first in [False,True]:
    bad=0
    for ranges in specs:
        spec=",".join(f"{l+1}-{r+1}" for l,r in ranges)
        if insert_variant(list(ranges), trim_mode, modify_mode, stop_first)!=ACT[spec]: bad+=1
    results.append((bad, trim_mode, modify_mode, stop_first))
results.sort()
for r in results: print(r)
