    if num_fields == 0 || ranges.is_empty() {
        return Vec::new();
    }
    // Determine, for each field, which range "owns" it: among ranges covering
    // the field, the one with the smallest (low, high, position) key.
    // Fields are then emitted grouped by owner in range-list order, in
    // ascending field order within each owner.
    let mut owner: Vec<Option<usize>> = vec![None; num_fields];
    for field_idx in 0..num_fields {
        let pos = field_idx + 1; // 1-based
        let mut best: Option<usize> = None;
        for (ri, r) in ranges.iter().enumerate() {
            if r.low <= pos && pos <= r.high {
                match best {
                    None => best = Some(ri),
                    Some(b) => {
                        let br = &ranges[b];
                        if (r.low, r.high, ri) < (br.low, br.high, b) {
                            best = Some(ri);
                        }
                    }
                }
            }
        }
        owner[field_idx] = best;
    }
    let mut out: Vec<usize> = Vec::new();
    for ri in 0..ranges.len() {
        for field_idx in 0..num_fields {
            if owner[field_idx] == Some(ri) {
                out.push(field_idx);
            }
        }
    }
    out
}"""
